-- FoodLink relational schema reference (MySQL 8+)
CREATE DATABASE IF NOT EXISTS foodlink_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE foodlink_db;
CREATE TABLE users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','owner','rider','customer') NOT NULL, status ENUM('Pending','Active','Suspended') DEFAULT 'Pending', business_name VARCHAR(150), logo_url TEXT, organization VARCHAR(80), delivery_fee DECIMAL(10,2) DEFAULT 0, wallet_balance DECIMAL(12,2) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE foods (id CHAR(36) PRIMARY KEY, owner_id CHAR(36) NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, category VARCHAR(80), price DECIMAL(10,2) NOT NULL, image_url TEXT, is_available BOOLEAN DEFAULT TRUE, sold_count INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE orders (id CHAR(36) PRIMARY KEY, customer_id CHAR(36) NOT NULL, owner_id CHAR(36) NOT NULL, rider_id CHAR(36), subtotal DECIMAL(12,2) NOT NULL, delivery_fee DECIMAL(10,2) DEFAULT 0, total DECIMAL(12,2) NOT NULL, payment_method ENUM('COD','GCash','Wallet') NOT NULL, payment_status VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, pickup_lat DECIMAL(10,7), pickup_lng DECIMAL(10,7), rider_lat DECIMAL(10,7), rider_lng DECIMAL(10,7), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(rider_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id CHAR(36) NOT NULL, food_id CHAR(36) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(food_id) REFERENCES foods(id));
CREATE TABLE notifications (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, title VARCHAR(180), message TEXT, is_read BOOLEAN DEFAULT FALSE, order_id CHAR(36), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE chat_messages (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL, sender_id CHAR(36) NOT NULL, message TEXT NOT NULL, reply_to CHAR(36), reaction VARCHAR(16), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(sender_id) REFERENCES users(id));
CREATE TABLE wallet_transactions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, order_id CHAR(36), transaction_type VARCHAR(40) NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_reference VARCHAR(190), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE ratings (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL UNIQUE, customer_id CHAR(36) NOT NULL, food_id CHAR(36) NOT NULL, stars TINYINT NOT NULL CHECK(stars BETWEEN 1 AND 5), review TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(food_id) REFERENCES foods(id));
CREATE INDEX idx_orders_customer ON orders(customer_id,created_at); CREATE INDEX idx_orders_owner ON orders(owner_id,status); CREATE INDEX idx_orders_rider ON orders(rider_id,status); CREATE INDEX idx_notifications_user_read ON notifications(user_id,is_read);
